import{_ as d,a0 as o,w as p,s as l,ao as r,I as i,x as s,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"試試動態窗口管理器 dwm 吧 | LCTT x X-CMD","titleTemplate":false,"description":"試試動態窗口管理器 dwm 吧 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"試試動態窗口管理器 dwm 吧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"試試動態窗口管理器 dwm 吧 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190318 Let-s try dwm - dynamic window manager","title":"試試動態窗口管理器 dwm 吧","tag":"201908","desc":""},"relativePath":"201908/20190318 Let-s try dwm - dynamic window manager.md","filePath":"[post].md"}'),c={name:"201908/20190318 Let-s try dwm - dynamic window manager.md"};function m(h,a,g,u,k,f){const e=o("Link");return p(),l("div",null,[a[18]||(a[18]=r(`<h1 id="試試動態窗口管理器-dwm-吧" tabindex="-1">試試動態窗口管理器 dwm 吧 <a class="header-anchor" href="#試試動態窗口管理器-dwm-吧" aria-label="Permalink to “試試動態窗口管理器 dwm 吧”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/dwm-magazine-image-816x345.png" alt=""></p><p>如果你崇尚效率和極簡主義，並且正在為你的 Linux 桌面尋找新的窗口管理器，那麼你應該嘗試一下<ruby>動態窗口管理器<rt>dynamic window manager</rt></ruby> dwm。以不到 2000 標準行的代碼寫就的 dwm，是一個速度極快而功能強大，且可高度定製的窗口管理器。</p><p>你可以在平鋪、單片和浮動佈局之間動態選擇，使用標籤將窗口組織到多個工作區，並使用鍵盤快捷鍵快速導航。本文將幫助你開始使用 dwm。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>要在 Fedora 上安裝 dwm，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install dwm dwm-user</span></span></code></pre></div><p><code>dwm</code> 包會安裝窗口管理器本身，<code>dwm-user</code> 包顯著簡化了配置，本文稍後將對此進行説明。</p><p>此外，為了能夠在需要時鎖定屏幕，我們還將安裝 <code>slock</code>，這是一個簡單的 X 顯示鎖屏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install slock</span></span></code></pre></div><p>當然，你可以根據你的個人喜好使用其它的鎖屏。</p><h3 id="快速入門" tabindex="-1">快速入門 <a class="header-anchor" href="#快速入門" aria-label="Permalink to “快速入門”">​</a></h3><p>要啓動 dwm，在登錄屏選擇 “dwm-user” 選項。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/choosing-dwm-1024x469.png" alt=""></p><p>登錄後，你將看到一個非常簡單的桌面。事實上，頂部唯一的一個面板列出了代表工作空間的 9 個標籤和一個代表窗户佈局的 <code>[]=</code> 符號。</p><h4 id="啓動應用" tabindex="-1">啓動應用 <a class="header-anchor" href="#啓動應用" aria-label="Permalink to “啓動應用”">​</a></h4><p>在查看佈局之前，首先啓動一些應用程序，以便你可以隨時使用佈局。可以通過按 <code>Alt+p</code> 並鍵入應用程序的名稱，然後回車來啓動應用程序。還有一個快捷鍵 <code>Alt+Shift+Enter</code> 用於打開終端。</p><p>現在有一些應用程序正在運行了，請查看佈局。</p><h4 id="佈局" tabindex="-1">佈局 <a class="header-anchor" href="#佈局" aria-label="Permalink to “佈局”">​</a></h4><p>默認情況下有三種佈局：平鋪佈局，單片佈局和浮動佈局。</p><p>平鋪佈局由條形圖上的 <code>[]=</code> 表示，它將窗口組織為兩個主要區域：左側為主區域，右側為堆疊區。你可以按 <code>Alt+t</code> 激活平鋪佈局。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/dwm-desktop-1024x593.png" alt=""></p><p>平鋪佈局背後的想法是，主窗口放在主區域中，同時仍然可以看到堆疊區中的其他窗口。你可以根據需要在它們之間快速切換。</p><p>要在兩個區域之間交換窗口，請將鼠標懸停在堆疊區中的一個窗口上，然後按 <code>Alt+Enter</code> 將其與主區域中的窗口交換。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/03/Screenshot-2019-03-15-at-11.12.32-1024x592.png" alt=""></p><p>單片佈局由頂部欄上的 <code>[N]</code> 表示，可以使你的主窗口占據整個屏幕。你可以按 <code>Alt+m</code> 切換到它。</p><p>最後，浮動佈局可讓你自由移動和調整窗口大小。它的快捷方式是 <code>Alt+f</code>，頂欄上的符號是 <code>&gt;&lt;&gt;</code>。</p><h4 id="工作區和標籤" tabindex="-1">工作區和標籤 <a class="header-anchor" href="#工作區和標籤" aria-label="Permalink to “工作區和標籤”">​</a></h4><p>每個窗口都分配了一個頂部欄中列出的標籤（1-9）。要查看特定標籤，請使用鼠標單擊其編號或按 <code>Alt+1..9</code>。你甚至可以使用鼠標右鍵單擊其編號，一次查看多個標籤。</p><p>通過使用鼠標突出顯示後，並按 <code>Alt+Shift+1..9</code>，窗口可以在不同標籤之間移動。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>為了使 dwm 儘可能簡約，它不使用典型的配置文件。而是你需要修改代表配置的 C 語言頭文件，並重新編譯它。但是不要擔心，在 Fedora 中你只需要簡單地編輯主目錄中的一個文件，而其他一切都會在後台發生，這要歸功於 Fedora 的維護者提供的 <code>dwm-user</code> 包。</p><p>首先，你需要使用類似於以下的命令將文件複製到主目錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.dwm</span></span>
<span class="line"><span>$ cp /usr/src/dwm-VERSION-RELEASE/config.def.h ~/.dwm/config.h</span></span></code></pre></div><p>你可以通過運行 <code>man dwm-start</code> 來獲取確切的路徑。</p><p>其次，只需編輯 <code>~/.dwm/config.h</code> 文件。例如，讓我們配置一個新的快捷方式：通過按 <code>Alt+Shift+L</code> 來鎖定屏幕。</p><p>考慮到我們已經安裝了本文前面提到的 <code>slock</code> 包，我們需要在文件中添加以下兩行以使其工作：</p><p>在 <code>/* commands */</code> 註釋下，添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>static const char *slockcmd[] = { &quot;slock&quot;, NULL };</span></span></code></pre></div><p>添加下列行到 <code>static Key keys[]</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{ MODKEY|ShiftMask, XK_l, spawn, {.v = slockcmd } },</span></span></code></pre></div><p>最終，它應該看起來如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span> /* commands */</span></span>
<span class="line"><span> static char dmenumon[2] = &quot;0&quot;; /* component of dmenucmd, manipulated in spawn() */</span></span>
<span class="line"><span> static const char *dmenucmd[] = { &quot;dmenu_run&quot;, &quot;-m&quot;, dmenumon, &quot;-fn&quot;, dmenufont, &quot;-nb&quot;, normbgcolor, &quot;-nf&quot;, normfgcolor, &quot;-sb&quot;, selbgcolor, &quot;-sf&quot;, selfgcolor, NULL };</span></span>
<span class="line"><span> static const char *termcmd[]  = { &quot;st&quot;, NULL };</span></span>
<span class="line"><span> static const char *slockcmd[] = { &quot;slock&quot;, NULL };</span></span>
<span class="line"><span></span></span>
<span class="line"><span> static Key keys[] = {</span></span>
<span class="line"><span>     /* modifier                     key        function        argument */</span></span>
<span class="line"><span>     { MODKEY|ShiftMask,             XK_l,      spawn,          {.v = slockcmd } },</span></span>
<span class="line"><span>     { MODKEY,                       XK_p,      spawn,          {.v = dmenucmd } },</span></span>
<span class="line"><span>     { MODKEY|ShiftMask,             XK_Return, spawn,          {.v = termcmd } },</span></span>
<span class="line"><span> ...</span></span></code></pre></div><p>保存文件。</p><p>最後，按 <code>Alt+Shift+q</code> 註銷，然後重新登錄。<code>dwm-user</code> 包提供的腳本將識別你已更改主目錄中的<code>config.h</code> 文件，並會在登錄時重新編譯 dwm。因為 dwm 非常小，它快到你甚至都不會注意到它重新編譯了。</p><p>你現在可以嘗試按 <code>Alt+Shift+L</code> 鎖定屏幕，然後輸入密碼並按回車鍵再次登錄。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你崇尚極簡主義並想要一個非常快速而功能強大的窗口管理器，dwm 可能正是你一直在尋找的。但是，它可能不適合初學者，你可能需要做許多其他配置才能按照你的喜好進行配置。</p>`,48)),i("p",null,[a[1]||(a[1]=s("要了解有關 dwm 的更多信息，請參閲該項目的主頁： ",-1)),t(e,{href:"https://dwm.suckless.org/"},{default:n(()=>[...a[0]||(a[0]=[s("https://dwm.suckless.org/",-1)])]),_:1}),a[2]||(a[2]=s("。",-1))]),a[19]||(a[19]=i("hr",null,null,-1)),i("p",null,[a[4]||(a[4]=s("via: ",-1)),t(e,{href:"https://fedoramagazine.org/lets-try-dwm-dynamic-window-manger/"},{default:n(()=>[...a[3]||(a[3]=[s("https://fedoramagazine.org/lets-try-dwm-dynamic-window-manger/",-1)])]),_:1})]),i("p",null,[a[9]||(a[9]=s("作者：",-1)),t(e,{href:"https://fedoramagazine.org/author/asamalik/"},{default:n(()=>[...a[5]||(a[5]=[s("Adam Šamalík",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[7]||(a[7]=[s("wxy",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const x=d(c,[["render",m]]);export{y as __pageData,x as default};
